// C tests of the smoketest's pure helpers (#1589), built by `make selftest` as its own binary and run
// by run.sh under the same sanitizers. It never feeds the coverage run, which comes from the
// mods/coverage/ tests alone, and it replaces none of them: a behaviour enters the smoketest only
// through a committed grug test.
//
// Every expected number below is a known-answer vector printed by java.util.Random on the local JDK:
//   $ java -version
//   openjdk version "21.0.13.1" 2026-11-17
//   OpenJDK Runtime Environment (build 21.0.13.1+2)
// Each row is one `new Random(seed)` followed by its calls in the order of the columns, so a draw
// depends on every draw before it. Doubles are printed with Double.toHexString, which is exact.
#define main smoketest_main
#include "smoketest.c"
#undef main

static int checks, failures;
#define CHECK(cond, ...) do { checks++; if (!(cond)) { failures++; printf("SELFTEST FAIL line %d: ", __LINE__); printf(__VA_ARGS__); printf("\n"); } } while (0)

struct vec {
    long long seed;
    int next_int[4];              // nextInt(), four calls
    int bound10[4];               // nextInt(10), a bound that is not a power of two
    int bound16[4];               // nextInt(16), a power of two
    int bound1000[4];             // nextInt(1000)
    int bound_max[4];             // nextInt(2147483647)
    double next_float[3];         // nextFloat()
    double next_double[3];        // nextDouble()
    double gaussian[5];           // nextGaussian(), an odd count so the cache is left full
};

// seed 42, 0 and 123456789012345, generated by Gen.java in this directory: `java .github/smoketest/Gen.java`
static const struct vec vecs[] = {
    {42LL, {-1170105035, 234785527, -1360544799, 205897768}, {0, 5, 5, 8}, {10, 1, 14, 7}, {276, 292, 476, 32}, {995688456, 1636576170, 1681268743, 2143572209}, {0x1.d6b22p-1, 0x1.3735ep-3, 0x1.bef77cp-2}, {0x1.c25ae2bff9d9cp-2, 0x1.dc7bb0b17b05ep-1, 0x1.98b90616b4568p-1}, {-0x1.db0091658e302p-1, -0x1.b7916f10a0315p-2, -0x1.5347487c1a372p0, -0x1.6ef432ef24896p-1, -0x1.7e1d6c3dcd4f5p-1}},
    {0LL, {-1155484576, -723955400, 1033096058, -1690734402}, {5, 3, 1, 1}, {9, 12, 5, 4}, {473, 262, 95, 844}, {1888030084, 49567875, 2021317241, 377907320}, {0x1.198d88p-2, 0x1.407248p-2, 0x1.07fb38p-3}, {0x1.78cea32587af8p-2, 0x1.690caa02f9778p-1, 0x1.6b828bf723p-10}, {-0x1.9f9198b440a79p-3, 0x1.aa6d154e39dc4p-6, -0x1.f868685defc2fp-1, -0x1.b50146fff6cbcp-1, 0x1.97e41e94f68acp-2}},
    {123456789012345LL, {-1421006947, -2071311287, -583755257, -1678701992}, {5, 8, 0, 9}, {13, 6, 13, 9}, {156, 768, 488, 241}, {1448108067, 496414028, 1442016227, 479138592}, {0x1.8dfd8p-4, 0x1.bf1108p-1, 0x1.326962p-1}, {0x1.d9b7564ed3b8ep-2, 0x1.6150963abdf94p-3, 0x1.b2f13fcb67b89p-1}, {-0x1.c911b23047d2cp-1, -0x1.4ed9c86b08351p-3, -0x1.990077d6868c3p-2, -0x1.5f1c5216c0266p-1, -0x1.cb48e6037a7f4p0}},
};

static void test_random(void) {
    for (size_t v = 0; v < sizeof vecs / sizeof vecs[0]; v++) {
        const struct vec* e = &vecs[v];
        rnd_set_seed(e->seed);
        for (int i = 0; i < 4; i++) CHECK(rnd_next(32) == e->next_int[i], "seed %lld nextInt() #%d", e->seed, i);
        for (int i = 0; i < 4; i++) CHECK(rnd_next_int(10) == e->bound10[i], "seed %lld nextInt(10) #%d", e->seed, i);
        for (int i = 0; i < 4; i++) CHECK(rnd_next_int(16) == e->bound16[i], "seed %lld nextInt(16) #%d", e->seed, i);
        for (int i = 0; i < 4; i++) CHECK(rnd_next_int(1000) == e->bound1000[i], "seed %lld nextInt(1000) #%d", e->seed, i);
        for (int i = 0; i < 4; i++) CHECK(rnd_next_int(2147483647u) == e->bound_max[i], "seed %lld nextInt(MAX) #%d", e->seed, i);
        for (int i = 0; i < 3; i++) CHECK(rnd_float() == e->next_float[i], "seed %lld nextFloat() #%d", e->seed, i);
        for (int i = 0; i < 3; i++) CHECK(rnd_double() == e->next_double[i], "seed %lld nextDouble() #%d", e->seed, i);
        for (int i = 0; i < 5; i++) CHECK(rnd_gaussian() == e->gaussian[i], "seed %lld nextGaussian() #%d", e->seed, i);
    }
    // A bound of 1431655765 makes the first draw of seed 0 hit Java's rejection loop (u - r + m
    // overflows), so the result comes from a later draw. new Random(0).nextInt(1431655765) is 516548029
    // on the local JDK above.
    rnd_set_seed(0);
    CHECK(rnd_next_int(1431655765u) == 516548029, "rejection loop");
    // nextInt(1) is always 0 and consumes one draw: the next nextInt() follows it.
    rnd_set_seed(42);
    CHECK(rnd_next_int(1) == 0, "nextInt(1)");
    CHECK(rnd_next(32) == 234785527, "draw after nextInt(1)");
    // rnd_reset is new Random(42), so the first nextInt() is the seed 42 vector's first.
    rnd_reset();
    CHECK(rnd_next(32) == -1170105035, "rnd_reset is seed 42");
    // new Random(42).nextGaussian() three times (java.util.Random, same JDK): the second call returns
    // the cached value of the first pair. Setting a seed discards that cache, as Java's setSeed does.
    rnd_set_seed(42);
    CHECK(rnd_gaussian() == 0x1.2453e82115d86p0, "first gaussian of seed 42");
    CHECK(rnd_gaussian() == 0x1.d6bca38120847p-1, "cached second gaussian");
    CHECK(rnd_gaussian() == -0x1.e654eb7a040c2p-1, "third gaussian starts a new pair");
    rnd_set_seed(42);
    (void)rnd_gaussian();
    rnd_set_seed(42);
    CHECK(rnd_gaussian() == 0x1.2453e82115d86p0, "setSeed clears the cached gaussian");
}

// strict_log is fdlibm's log. The seed 42 gaussians above are its known-answer test against Java's
// StrictMath.log (glibc's log is one bit off there); these rows reach its other paths, and their
// expected values are mathematical constants, not JDK output.
static void test_strict_log(void) {
    CHECK(strict_log(1.0) == 0.0, "log 1");
    CHECK(strict_log(0.0) == -INFINITY, "log 0");
    CHECK(isnan(strict_log(-1.0)), "log negative");
    CHECK(isinf(strict_log(INFINITY)) && strict_log(INFINITY) > 0, "log infinity");
    CHECK(isnan(strict_log(NAN)), "log nan");
    CHECK(fabs(strict_log(4.9e-324) - (-744.4400719213812)) < 1e-9, "log of the smallest subnormal");
    CHECK(fabs(strict_log(1.0 + 0x1p-30) - (0x1p-30 - 0x1p-61)) < 1e-24, "log near 1");
    CHECK(fabs(strict_log(2.0) - 0.6931471805599453) < 1e-15, "log 2");
    CHECK(fabs(strict_log(1e300) - 690.7755278982137) < 1e-12, "log 1e300");
}

static void test_index(void) {
    CHECK(check_index(0, 1, true) == IDX_OK, "first of one");
    CHECK(check_index(2, 3, true) == IDX_OK, "last of three");
    CHECK(check_index(3, 3, true) == IDX_NO_RECORD, "one past the end");
    CHECK(check_index(0, 0, true) == IDX_NO_RECORD, "empty list");
    CHECK(check_index(0, 0, false) == IDX_NO_RECORD, "list never created");
    CHECK(check_index(1e9, 3, true) == IDX_NO_RECORD, "far past the end");
    CHECK(check_index(2147483647.0, 3, true) == IDX_NO_RECORD, "largest int index");
    CHECK(check_index(2147483648.0, 3, true) == IDX_NOT_WHOLE, "past the int range");
    CHECK(check_index(-1, 3, true) == IDX_NOT_WHOLE, "negative");
    CHECK(check_index(-0.5, 3, true) == IDX_NOT_WHOLE, "negative fraction");
    CHECK(check_index(1.5, 3, true) == IDX_NOT_WHOLE, "fraction");
    CHECK(check_index(NAN, 3, true) == IDX_NOT_WHOLE, "nan");
    CHECK(check_index(INFINITY, 3, true) == IDX_NOT_WHOLE, "infinity");
    CHECK(check_index(-INFINITY, 3, true) == IDX_NOT_WHOLE, "negative infinity");
}

// number_text is String.from_number's text. The expected strings are what the adapter's numberText
// answers on a real JDK (openjdk 21.0.13.1): the whole numbers through
// new BigDecimal(v).toBigInteger().toString(), the others through Double.toString(v). Gen.java
// prints these exact vectors (the NUMBER_TEXT lines).
static void test_number_text(void) {
    static const struct { double v; const char* want; } t[] = {
        {2.5, "2.5"}, {-0.25, "-0.25"}, {0.1 + 0.2, "0.30000000000000004"}, {123456.789, "123456.789"},
        {0.001, "0.001"}, {1.0E-4, "1.0E-4"}, {1.5E-5, "1.5E-5"}, {-3.75E-7, "-3.75E-7"},
        {1.0 / 3, "0.3333333333333333"}, {NAN, "NaN"}, {INFINITY, "Infinity"}, {-INFINITY, "-Infinity"},
        {-0.0, "0"}, {1e20, "100000000000000000000"}, {1.2345678901234567e25, "12345678901234566097272832"},
        {4.9e-324, "4.9E-324"}, {0.5, "0.5"}, {9999999.5, "9999999.5"}, {12345678.9, "1.23456789E7"},
        {1e7 + 0.5, "1.00000005E7"}, {41, "41"}, {-7, "-7"},
    };
    for (size_t i = 0; i < sizeof t / sizeof *t; i++) {
        char buf[400];
        number_text(t[i].v, buf, sizeof buf);
        CHECK(!strcmp(buf, t[i].want), "number_text(%g) is %s, want %s", t[i].v, buf, t[i].want);
    }
    char big[400];
    number_text(1.7976931348623157e308, big, sizeof big);
    CHECK(strlen(big) == 309 && !strncmp(big, "17976931348623157081452742373170435679807056752584", 50), "the largest double is 309 digits");
}
// Text counts code points: U+1F600 is four bytes and one character, as in codePointCount.
static void test_code_points(void) {
    CHECK(cp_count("") == 0, "empty");
    CHECK(cp_count("abc") == 3, "ascii");
    CHECK(cp_count("\xC3\xA9") == 1, "two byte");
    CHECK(cp_count("\xE2\x82\xAC") == 1, "three byte");
    CHECK(cp_count("a\xF0\x9F\x98\x80z") == 3, "four byte");
    const char* t = "a\xF0\x9F\x98\x80z";
    CHECK(cp_offset(t, 0) == t, "offset 0");
    CHECK(cp_offset(t, 1) == t + 1, "offset 1");
    CHECK(cp_offset(t, 2) == t + 5, "offset past the four byte character");
    CHECK(cp_offset(t, 3) == t + 6, "offset at the end");
}

// match_recipe: where a shaped recipe may sit in the grid, and what a shapeless one ignores. The expected
// answers are Minecraft's own rules (a shaped pattern slides, every other cell stays empty; a shapeless
// recipe takes exactly its ingredients in any order), not JDK output.
static void test_match_recipe(void) {
    static const struct recipe rs[] = {
        {1, 2, 1, "pair", 1, {"a", "b"}},
        {1, 2, 2, "stair", 1, {"s", "", "s", "s"}},
        {0, 2, 1, "loose", 1, {"x", "y"}},
    };
    const char* stair[9] = {"s", NULL, NULL, "s", "s"};
    const char* flipped[9] = {NULL, "s", NULL, "s", "s"};
    const char* mirrored_pair[9] = {NULL, NULL, NULL, "b", "a"};
    const char* at_corner[9] = {"a", "b"};
    const char* slid[9] = {NULL, NULL, NULL, NULL, NULL, NULL, NULL, "a", "b"};
    const char* extra[9] = {"a", "b", NULL, NULL, "a"};
    const char* swapped[9] = {NULL, "y", NULL, NULL, NULL, "x"};
    const char* shy[9] = {"x", "x"};
    const char* many[9] = {"x", "y", "y"};
    const char* empty[9] = {NULL};
    CHECK(match_recipe(rs, 3, at_corner) == &rs[0], "a shaped recipe matches in the grid's corner");
    CHECK(match_recipe(rs, 3, slid) == &rs[0], "a shaped recipe slides to the last row");
    CHECK(match_recipe(rs, 3, extra) == NULL, "a stray item beside a shaped recipe stops the match");
    CHECK(match_recipe(rs, 3, swapped) == &rs[2], "a shapeless recipe ignores order and position");
    CHECK(match_recipe(rs, 3, shy) == NULL, "a shapeless recipe needs each ingredient");
    CHECK(match_recipe(rs, 3, many) == NULL, "a shapeless recipe takes no extra item");
    CHECK(match_recipe(rs, 3, stair) == &rs[1], "a shaped recipe matches as written");
    CHECK(match_recipe(rs, 3, flipped) == &rs[1], "a shaped recipe matches mirrored");
    CHECK(match_recipe(rs, 3, mirrored_pair) == &rs[0], "a mirrored pair matches");
    CHECK(match_recipe(rs, 3, empty) == NULL, "an empty grid matches nothing");
}

static void test_double_text(void) {
    char m[64];
    struct { double v; const char* want; } cases[] = {
        {0.0, "0.0"}, {-0.0, "-0.0"}, {128, "128.0"}, {100, "100.0"}, {-3, "-3.0"}, {1.5, "1.5"}, {0.001, "0.001"},
        {1e7, "1.0E7"}, {2147483648.0, "2.147483648E9"}, {1e-4, "1.0E-4"}, {1.5e300, "1.5E300"},
        {NAN, "NaN"}, {INFINITY, "Infinity"}, {-INFINITY, "-Infinity"},
    };
    for (size_t i = 0; i < sizeof cases / sizeof *cases; i++) {
        double_text(cases[i].v, m, sizeof m);
        CHECK(!strcmp(m, cases[i].want), "Double.toString(%g) is %s, got %s", cases[i].v, cases[i].want, m);
    }
}

static void test_nbt_helpers(void) {
    char m[256];
    // Messages and verdicts mirror GrugBlockEntityNbt.parsePath and checkValue.
    CHECK(!nbt_path_problem("GrugNumbers.0.Value", m, sizeof m), "a path of keys and an index is fine");
    CHECK(nbt_path_problem("a..b", m, sizeof m) && !strcmp(m, "The path \"a..b\" has an empty part."), "%s", m);
    CHECK(nbt_path_problem("", m, sizeof m) && !strcmp(m, "The path \"\" has an empty part."), "%s", m);
    CHECK(nbt_path_problem("0.a", m, sizeof m) && !strcmp(m, "The path \"0.a\" has an index that does not follow a key."), "%s", m);
    CHECK(nbt_path_problem("a.1.2.b", m, sizeof m) && !strcmp(m, "The path \"a.1.2.b\" has an index that does not follow a key."), "%s", m);
    CHECK(nbt_path_problem("a.1234567890.b", m, sizeof m) && !strcmp(m, "The index 1234567890 in the path \"a.1234567890.b\" is too large."), "%s", m);
    CHECK(!nbt_path_problem("a.123456789.b", m, sizeof m), "nine digits is the largest index");
    CHECK(nbt_path_problem("a.1", m, sizeof m) && !strcmp(m, "The path \"a.1\" has to end in a key, not an index."), "%s", m);
    CHECK(!nbt_value_problem("float", 0.5, m, sizeof m) && !nbt_value_problem("double", -1e300, m, sizeof m), "a float or a double takes any number");
    CHECK(!nbt_value_problem("byte", 127, m, sizeof m) && !nbt_value_problem("byte", -128, m, sizeof m), "byte bounds are in");
    CHECK(nbt_value_problem("byte", 128, m, sizeof m) && !strcmp(m, "A byte has to be a whole number from -128 to 127, not 128.0."), "%s", m);
    CHECK(nbt_value_problem("short", 1.5, m, sizeof m) && !strcmp(m, "A short has to be a whole number from -32768 to 32767, not 1.5."), "%s", m);
    CHECK(nbt_value_problem("int", 2147483648.0, m, sizeof m) && !strcmp(m, "A int has to be a whole number from -2147483648 to 2147483647, not 2.147483648E9."), "%s", m);
    CHECK(nbt_value_problem("long", 1.5, m, sizeof m) && !strcmp(m, "A long has to be a whole number from -9223372036854775808 to 9223372036854775807, not 1.5."), "%s", m);
    CHECK(!nbt_value_problem("long", 9223372036854775807.0, m, sizeof m), "2^63 passes, as Java's double comparison does");
    CHECK(nbt_value_problem("int", NAN, m, sizeof m), "NaN is not whole");
}

int main(void) {
    test_random();
    test_strict_log();
    test_index();
    test_number_text();
    test_code_points();
    test_match_recipe();
    test_double_text();
    test_nbt_helpers();
    printf("selftest: %d checks, %d failed\n", checks, failures);
    return failures ? 1 : 0;
}
